{"description": "从 Pexels 页面抓候选图", "command": "$dir="C:\Users\九幽\.dsh-qq\avatar"
$targets = @(
 @{n='p1'; url='https://www.pexels.com/photo/29482609/'},
 @{n='p2'; url='https://www.pexels.com/photo/30553790/'}
)
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
foreach($t in $targets){
  try{
    $r = Invoke-WebRequest -Uri $t.url -UseBasicParsing -TimeoutSec 30 -Headers @{'User-Agent'='Mozilla/5.0 (Windows NT 10.0; Win64; x64)'}
    $m = [regex]::Matches($r.Content,'https://images\.pexels\.com/photos/\d+/[A-Za-z0-9\-_\.]+\.(jpg|jpeg|png)')
    if($m.Count -gt 0){
      $img = ($m | ForEach-Object { $_.Value } | Select-Object -Unique)[0]
      $img800 = $img + '?auto=compress&cs=tinysrgb&w=800'
      $out = Join-Path $dir ($t.n + '.jpg')
      Invoke-WebRequest -Uri $img800 -OutFile $out -UseBasicParsing -TimeoutSec 60 -Headers @{'User-Agent'='Mozilla/5.0'}
      "$($t.n) OK -> $out ($((Get-Item $out).Length) bytes)"
    } else { "$($t.n) 页面里没有 images.pexels.com（状态 $($r.StatusCode)）" }
  } catch { "$($t.n) 失败: $($_.Exception.Message)" }
}"}

