} catch {
    W "restart failed: $($_.Exception.Message)"
}
for ($i = 0; $i -lt 20; $i++) {
    Start-Sleep -Seconds 2
    $listen = Get-NetTCPConnection -State Listen -LocalPort 8790 -ErrorAction SilentlyContinue
    if ($listen) { W "port 8790 listening PID=$($listen.OwningProcess -join ',')"; break }
}
W "wrapper done"
